  extra=f"tl.fromTo('#{sid}-b',{{opacity:0,x:24}},{{opacity:1,x:0,duration:0.4,ease:'power2.out'}},4);tl.fromTo('#{sid}-c',{{opacity:0,x:24}},{{opacity:1,x:0,duration:0.4,ease:'power2.out'}},9);tl.fromTo('#{sid}-end',{{opacity:0,y:24}},{{opacity:1,y:0,duration:0.4,ease:'power2.out'}},16);"
