start=0;hosts=[];srt=[]
def tc(s):
 ms=round(s*1000);return f'{ms//3600000:02}:{ms//60000%60:02}:{ms//1000%60:02},{ms%1000:03}'
for i,r in enumerate(rows):
 d=round(r['duration']+0.9,3);sid='scene'+str(i+1)
